# Search for key sections
patterns = ['[grader tail]', '[facts]', '[first wrong step]', '[grade]', '[checkpoint]', 'STATUS.json', 'c_m02', 'c_m03', 'c_m05', 'c_m11', 'c_m15', 'c_m17', 'c_m23', 'c_m25', 'c_m28']
for p in patterns:
    results = await CONTEXT.search(p)
    if results:
        print(f"'{p}' found {len(results)} times")
        for r in results[:3]:
            print(f"  offset={r['offset']}, snippet={r['snippet'][:100]}")
    else:
        print(f"'{p}' NOT found")
